// Checks for the optional PIN (src/privacy.js): only a salted PBKDF2 hash is kept, a wrong PIN is refused and
// counted, the PIN locks after the allowed tries, and each person's PIN is their own.
// Run: npm test (Node 18+). Uses an in-memory store, never a browser's storage.
// Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { webcrypto } from 'node:crypto';

// Node 18 may keep Web Crypto under node:crypto only; Node 19 and newer also have it as globalThis.crypto.
if (!globalThis.crypto || !globalThis.crypto.subtle) Object.defineProperty(globalThis, 'crypto', { value: webcrypto, configurable: true });
const { PIN_RULES, checkPin, clearPin, hasPin, pinAvailable, pinLocked, pinProblem, pinTriesLeft, setPin, usePinStorage } = await import('../src/privacy.js');

function freshStorage() {
  const map = new Map();
  usePinStorage({ getItem: (k) => (map.has(k) ? map.get(k) : null), setItem: (k, v) => map.set(k, String(v)), removeItem: (k) => map.delete(k) });
  return map;
}

test('a PIN is kept only as a salted PBKDF2 hash, and only the right PIN opens', async () => {
  const map = freshStorage();
  assert.equal(pinAvailable(), true);
  assert.equal(hasPin('crew-1'), false);
  assert.equal(await checkPin('crew-1', '1234'), false, 'no PIN set: nothing to open');
  await setPin('crew-1', '482916');
  assert.equal(hasPin('crew-1'), true);
  const [[key, raw]] = [...map];
  assert.equal(key, 'jff-pin-v1:crew-1', 'the storage key holds the id only');
  assert.ok(!raw.includes('482916'), 'the PIN itself is never stored');
  const r = JSON.parse(raw);
  assert.equal(r.kdf, 'PBKDF2-HMAC-SHA-256');
  assert.ok(r.iterations >= 200000, 'at least 200,000 iterations');
  assert.equal(r.iterations, PIN_RULES.iterations);
  assert.equal(Buffer.from(r.salt, 'base64').length, 16, 'a 128-bit salt');
  assert.equal(Buffer.from(r.hash, 'base64').length, 32);
  assert.equal(await checkPin('crew-1', '482916'), true);
  assert.equal(await checkPin('crew-1', '482917'), false);
  assert.equal(pinTriesLeft('crew-1'), PIN_RULES.maxTries - 1);
  assert.equal(await checkPin('crew-1', '482916'), true, 'the right PIN still opens');
  assert.equal(pinTriesLeft('crew-1'), PIN_RULES.maxTries, 'and the count starts again');
});

test('the same PIN gives a different hash each time (a fresh salt), and every person has their own', async () => {
  const map = freshStorage();
  await setPin('crew-1', '1234');
  await setPin('crew-2', '1234');
  const a = JSON.parse(map.get('jff-pin-v1:crew-1'));
  const b = JSON.parse(map.get('jff-pin-v1:crew-2'));
  assert.notEqual(a.salt, b.salt);
  assert.notEqual(a.hash, b.hash);
  await setPin('crew-2', '9876');
  assert.equal(await checkPin('crew-1', '1234'), true);
  assert.equal(await checkPin('crew-2', '1234'), false);
  clearPin('crew-2');
  assert.equal(hasPin('crew-2'), false);
  assert.equal(hasPin('crew-1'), true, 'clearing one person leaves the others');
});

test('after 10 wrong PINs in a row the PIN locks until it is reset', async () => {
  const map = freshStorage();
  await setPin('crew-3', '2468');
  // Nine wrong tries already counted, written as the screen would leave them.
  map.set('jff-pin-v1:crew-3', JSON.stringify({ ...JSON.parse(map.get('jff-pin-v1:crew-3')), fails: PIN_RULES.maxTries - 1 }));
  assert.equal(pinTriesLeft('crew-3'), 1);
  assert.equal(pinLocked('crew-3'), false);
  assert.equal(await checkPin('crew-3', '0000'), false);
  assert.equal(pinLocked('crew-3'), true);
  assert.equal(await checkPin('crew-3', '2468'), false, 'locked: not even the right PIN opens');
  clearPin('crew-3');
  assert.equal(pinLocked('crew-3'), false);
  await setPin('crew-3', '1357');
  assert.equal(await checkPin('crew-3', '1357'), true);
});

test('PINs that cannot be used are refused with a reason, and a malformed try counts as wrong', async () => {
  freshStorage();
  for (const bad of ['123', '12a4', '', ' 1234', '1234567890123', 1234, null]) {
    assert.ok(pinProblem(bad), String(bad));
    await assert.rejects(setPin('crew-1', bad), String(bad));
  }
  assert.equal(pinProblem('1234'), null);
  assert.equal(pinProblem('123456789012'), null);
  await setPin('crew-1', '1234');
  assert.equal(await checkPin('crew-1', 'abcd'), false);
  assert.equal(pinTriesLeft('crew-1'), PIN_RULES.maxTries - 1);
  assert.throws(() => hasPin('../x'), TypeError);
  await assert.rejects(setPin('Crew 1', '1234'), TypeError);
});

test('a stored record that was tampered with does not open', async () => {
  const map = freshStorage();
  await setPin('crew-4', '5555');
  const r = JSON.parse(map.get('jff-pin-v1:crew-4'));
  map.set('jff-pin-v1:crew-4', JSON.stringify({ ...r, iterations: 1 }));
  assert.equal(await checkPin('crew-4', '5555'), false, 'too few iterations: not trusted');
  map.set('jff-pin-v1:crew-4', JSON.stringify({ ...r, fails: 'none' }));
  assert.equal(await checkPin('crew-4', '5555'), false, 'an unreadable counter counts as locked');
  map.set('jff-pin-v1:crew-4', 'not json');
  assert.equal(hasPin('crew-4'), false);
});

test('the PIN rules name their sources and are marked as drafts', () => {
  assert.equal(PIN_RULES.draft, true);
  assert.ok(PIN_RULES.minDigits >= 4 && PIN_RULES.maxTries <= 10 && PIN_RULES.iterations >= 200000 && PIN_RULES.saltBytes >= 16);
  for (const rule of PIN_RULES.rules) {
    assert.match(rule.src.url, /^https:\/\//);
    assert.doesNotMatch(rule.text, /[\u2013\u2014]/);
  }
});
